from __future__ import annotations

from datetime import datetime, timedelta

_MONTH_NAMES = {
    "JAN": 1,
    "FEB": 2,
    "MAR": 3,
    "APR": 4,
    "MAY": 5,
    "JUN": 6,
    "JUL": 7,
    "AUG": 8,
    "SEP": 9,
    "OCT": 10,
    "NOV": 11,
    "DEC": 12,
}

_WEEKDAY_NAMES = {
    "SUN": 0,
    "MON": 1,
    "TUE": 2,
    "WED": 3,
    "THU": 4,
    "FRI": 5,
    "SAT": 6,
}

# (name, low, high, names) for each field, in expression order.
_FIELDS = (
    ("minute", 0, 59, {}),
    ("hour", 0, 23, {}),
    ("day of month", 1, 31, {}),
    ("month", 1, 12, _MONTH_NAMES),
    ("day of week", 0, 7, _WEEKDAY_NAMES),
)


def _parse_value(text: str, low: int, high: int, names: dict[str, int]) -> int:
    name = text.upper()
    if name in names:
        value = names[name]
    elif text.isdigit():
        value = int(text)
    else:
        raise ValueError(f"invalid value {text!r}")
    if not low <= value <= high:
        raise ValueError(f"value {text!r} out of range {low}-{high}")
    return value


def _parse_field(text: str, low: int, high: int, names: dict[str, int]) -> set[int]:
    if not text:
        raise ValueError("empty field")

    values: set[int] = set()
    for item in text.split(","):
        if not item:
            raise ValueError(f"empty item in {text!r}")

        base, slash, step_text = item.partition("/")
        if slash:
            if not step_text.isdigit() or int(step_text) <= 0:
                raise ValueError(f"invalid step in {item!r}")
            step = int(step_text)
        else:
            step = 1

        if base == "*":
            start, end = low, high
        elif "-" in base:
            if base.count("-") != 1:
                raise ValueError(f"invalid range {base!r}")
            start_text, end_text = base.split("-")
            start = _parse_value(start_text, low, high, names)
            end = _parse_value(end_text, low, high, names)
            if start > end:
                raise ValueError(f"invalid range {base!r}")
        else:
            start = _parse_value(base, low, high, names)
            # A bare value stands alone; a value with a step runs to the end.
            end = high if slash else start

        values.update(range(start, end + 1, step))

    return values


def _parse(expression: str) -> tuple[
    set[int], set[int], set[int], set[int], set[int], bool, bool
]:
    fields = expression.split()
    if len(fields) != 5:
        raise ValueError("a cron expression must have exactly five fields")

    minutes = _parse_field(fields[0], *_FIELDS[0][1:])
    hours = _parse_field(fields[1], *_FIELDS[1][1:])
    days = _parse_field(fields[2], *_FIELDS[2][1:])
    months = _parse_field(fields[3], *_FIELDS[3][1:])
    weekdays = _parse_field(fields[4], *_FIELDS[4][1:])

    # Both 0 and 7 mean Sunday.
    weekdays = {value % 7 for value in weekdays}

    return (
        minutes,
        hours,
        days,
        months,
        weekdays,
        fields[2] != "*",
        fields[4] != "*",
    )


def _day_matches(
    day: datetime,
    days: set[int],
    weekdays: set[int],
    day_restricted: bool,
    weekday_restricted: bool,
) -> bool:
    day_match = day.day in days
    # datetime.weekday() is Monday=0; cron has Sunday=0.
    weekday_match = (day.weekday() + 1) % 7 in weekdays
    if day_restricted and weekday_restricted:
        return day_match or weekday_match
    return day_match and weekday_match


def next_run(expression: str, after: datetime) -> datetime:
    """The first time after ``after`` that ``expression`` fires."""
    minutes, hours, days, months, weekdays, day_restricted, weekday_restricted = (
        _parse(expression)
    )
    ordered_minutes = sorted(minutes)
    ordered_hours = sorted(hours)

    try:
        deadline = after.replace(year=after.year + 5)
    except ValueError:
        deadline = datetime.max

    try:
        start = after.replace(second=0, microsecond=0) + timedelta(minutes=1)
    except OverflowError:
        raise ValueError("no matching time within five years") from None

    day = start.date()
    last_day = deadline.date()
    while day <= last_day:
        if day.month in months and _day_matches(
            day, days, weekdays, day_restricted, weekday_restricted
        ):
            for hour in ordered_hours:
                for minute in ordered_minutes:
                    moment = datetime(day.year, day.month, day.day, hour, minute)
                    if moment <= after:
                        continue
                    if moment > deadline:
                        raise ValueError("no matching time within five years")
                    return moment
        if day == last_day:
            break
        day += timedelta(days=1)

    raise ValueError("no matching time within five years")

